-- =============================================================================
-- Bolsa de Trabajo · datos de configuración y de prueba (todos ficticios)
-- 2 cuentas admin, 10 empresas con perfil, logo y 5 búsquedas cada una, y 50
-- estudiantes con perfil completo. Clave de las cuentas de prueba: ver
-- infra/datos-prueba/usuarios_prueba.xlsx. Cómo importarlo: README.md, "Datos de prueba".
--
-- Sólo datos (las tablas las crean los servicios al arrancar). Reemplaza todo lo que haya
-- en los schemas auth, profile, jobs y matching. No incluye sesiones, tokens ni el outbox.
-- =============================================================================

BEGIN;
TRUNCATE auth.users, auth.companies, auth.refresh_sessions, auth.action_tokens,
         auth.account_event_deliveries,
         profile.profiles, profile.profiles_deleted, profile.company_profiles,
         profile.company_profiles_deleted, profile.company_logos, profile.deleted_accounts,
         jobs.jobs, jobs.jobs_deleted, jobs.deleted_accounts,
         matching.recommendations, matching.recommendation_requests,
         matching.recommendation_settings
  CASCADE;
COMMIT;

